public static boolean exist(RRBId _id)
{
    return (select firstonly RecId from RRBBookTable
        where RRBBookTable.Id == _id).RecId != 0;
}

public static RRBBookTable findRecId(RecId _recId)
{
    RRBBookTable bookTable;

    select firstonly bookTable
        where bookTable.RecId == _recId;

    return bookTable;
}

public static RRBBookTable find(RRBId _id)
{
    RRBBookTable bookTable;

    select firstonly bookTable
        where bookTable.Id == _id;

    return bookTable;
}

public static int selectCountByGenre(RRBGenreEnum _genre)
{
    RRBBookTable bookTable;

    select count(RecId) from bookTable
        group by Genre
        where bookTable.Genre == _genre;

    return bookTable.RecId;
}

[SysClientCacheDataMethod(true)]
public display RRBAuthorFullName dispAuthorFullName()
{
    RRBAuthorTable authorTable = RRBAuthorTable::findRecId(this.Author);

    return authorTable.FirstName + ' ' + authorTable.LastName;
}

[SysClientCacheDataMethod(true)]
public display RRBInventoryQty dispCurrentInventory()
{
    return this.currentInventory();
}

public Qty currentInventory(RecId _excludeTransactionRecId = 0)
{
    RRBBookInventoryTransaction transactions;

    select sum(Qty) from transactions
        where transactions.Book == this.RecId
        && transactions.RecId != _excludeTransactionRecId;

    return transactions.Qty;
}

public Common AuthorTableLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(RRBAuthorTable), _formReferenceControl);


    refTableLookup.parmQuery(this.getLookupQuery());
    refTableLookup.addLookupfield(fieldNum(RRBAuthorTable,Id));
    refTableLookup.addLookupfield(fieldNum(RRBAuthorTable,FirstName));
    refTableLookup.addLookupfield(fieldNum(RRBAuthorTable,LastName));
    refTableLookup.addLookupfield(fieldNum(RRBAuthorTable, IsDead));

    return refTableLookup.performFormLookup();
}

private Query getLookupQuery()
{
    Query q = new Query();
    QueryBuildDataSource qbds = q.addDataSource(tableNum(RRBAuthorTable));

    qbds.addRange(fieldNum(RRBAuthorTable, IsDead)).value(queryValue(NoYes::No));

    return q;
}

